1	// Utilities for manipulating markdown strings using AST parsing
2	// Uses mdast for accurate task detection that properly handles code blocks
3	
4	import type { Heading, ListItem } from "mdast";
5	import { fromMarkdown } from "mdast-util-from-markdown";
6	import { gfmFromMarkdown } from "mdast-util-gfm";
7	import { gfm } from "micromark-extension-gfm";
8	import { visit } from "unist-util-visit";
9	
10	interface TaskInfo {
11	  lineNumber: number;
12	  checked: boolean;
13	}
14	
15	// Extract all task list items from markdown using AST parsing
16	// This correctly ignores task-like patterns inside code blocks
17	function extractTasksFromAst(markdown: string): TaskInfo[] {
18	  const tree = fromMarkdown(markdown, {
19	    extensions: [gfm()],
20	    mdastExtensions: [gfmFromMarkdown()],
21	  });
22	
23	  const tasks: TaskInfo[] = [];
24	
25	  visit(tree, "listItem", (node: ListItem) => {
26	    // Only process actual task list items (those with a checkbox)
27	    if (typeof node.checked === "boolean" && node.position?.start.line) {
28	      tasks.push({
29	        lineNumber: node.position.start.line - 1, // Convert to 0-based
30	        checked: node.checked,
31	      });
32	    }
33	  });
34	
35	  return tasks;
36	}
37	
38	export function toggleTaskAtLine(markdown: string, lineNumber: number, checked: boolean): string {
39	  const lines = markdown.split("\n");
40	
41	  if (lineNumber < 0 || lineNumber >= lines.length) {
42	    return markdown;
43	  }
44	
45	  const line = lines[lineNumber];
46	
47	  // Match task list patterns: - [ ], - [x], - [X], etc.
48	  const taskPattern = /^(\s*[-*+]\s+)\[([ xX])\](\s+.*)$/;
49	  const match = line.match(taskPattern);
50	
51	  if (!match) {
52	    return markdown;
53	  }
54	
55	  const [, prefix, , suffix] = match;
56	  const newCheckmark = checked ? "x" : " ";
57	  lines[lineNumber] = `${prefix}[${newCheckmark}]${suffix}`;
58	
59	  return lines.join("\n");
60	}
61	
62	export function toggleTaskAtIndex(markdown: string, taskIndex: number, checked: boolean): string {
63	  const tasks = extractTasksFromAst(markdown);
64	
65	  if (taskIndex < 0 || taskIndex >= tasks.length) {
66	    return markdown;
67	  }
68	
69	  const task = tasks[taskIndex];
70	  return toggleTaskAtLine(markdown, task.lineNumber, checked);
71	}
72	
73	export function countTasks(markdown: string): {
74	  total: number;
75	  completed: number;
76	  incomplete: number;
77	} {
78	  const tasks = extractTasksFromAst(markdown);
79	
80	  const total = tasks.length;
81	  const completed = tasks.filter((t) => t.checked).length;
82	
83	  return {
84	    total,
85	    completed,
86	    incomplete: total - completed,
87	  };
88	}
89	
90	export function getTaskLineNumber(markdown: string, taskIndex: number): number {
91	  const tasks = extractTasksFromAst(markdown);
92	
93	  if (taskIndex < 0 || taskIndex >= tasks.length) {
94	    return -1;
95	  }
96	
97	  return tasks[taskIndex].lineNumber;
98	}
99	
100	export interface TaskItem {
101	  lineNumber: number;
102	  taskIndex: number;
103	  checked: boolean;
104	  content: string;
105	  indentation: number;
106	}
107	
108	export interface HeadingItem {
109	  text: string;
110	  level: 1 | 2 | 3 | 4;
111	  slug: string;
112	}
113	
114	/**
115	 * Slugify a string into a URL-friendly anchor ID.
116	 */
117	export function slugify(text: string): string {
118	  return text
119	    .toLowerCase()
120	    .trim()
121	    .replace(/[^\w\s-]/g, "")
122	    .replace(/[\s_]+/g, "-")
123	    .replace(/-+/g, "-")
124	    .replace(/^-|-$/g, "");
125	}
126	
127	/**
128	 * Extract h1–h4 headings from markdown content for outline navigation.
129	 */
130	export function extractHeadings(markdown: string): HeadingItem[] {
131	  const tree = fromMarkdown(markdown, {
132	    extensions: [gfm()],
133	    mdastExtensions: [gfmFromMarkdown()],
134	  });
135	
136	  const headings: HeadingItem[] = [];
137	  const slugCounts = new Map<string, number>();
138	
139	  visit(tree, "heading", (node: Heading) => {
140	    if (node.depth < 1 || node.depth > 4) return;
141	
142	    const text = getNodeText(node as unknown as MdastNode);
143	    if (!text) return;
144	
145	    let slug = slugify(text);
146	    const count = slugCounts.get(slug) || 0;
147	    slugCounts.set(slug, count + 1);
148	    if (count > 0) slug = `${slug}-${count}`;
149	
150	    headings.push({ text, level: node.depth as 1 | 2 | 3 | 4, slug });
151	  });
152	
153	  return headings;
154	}
155	
156	interface MdastNode {
157	  value?: string;
158	  children?: MdastNode[];
159	}
160	
161	function getNodeText(node: MdastNode): string {
162	  if (node.value) return node.value;
163	  if (node.children) return node.children.map(getNodeText).join("");
164	  return "";
165	}
166	
167	export function extractTasks(markdown: string): TaskItem[] {
168	  const tree = fromMarkdown(markdown, {
169	    extensions: [gfm()],
170	    mdastExtensions: [gfmFromMarkdown()],
171	  });
172	
173	  const lines = markdown.split("\n");
174	  const tasks: TaskItem[] = [];
175	  let taskIndex = 0;
176	
177	  visit(tree, "listItem", (node: ListItem) => {
178	    if (typeof node.checked === "boolean" && node.position?.start.line) {
179	      const lineNumber = node.position.start.line - 1;
180	      const line = lines[lineNumber];
181	
182	      // Extract indentation
183	      const indentMatch = line.match(/^(\s*)/);
184	      const indentation = indentMatch ? indentMatch[1].length : 0;
185	
186	      // Extract content (text after the checkbox)
187	      const contentMatch = line.match(/^\s*[-*+]\s+\[[ xX]\]\s+(.*)/);
188	      const content = contentMatch ? contentMatch[1] : "";
189	
190	      tasks.push({
191	        lineNumber,
192	        taskIndex: taskIndex++,
193	        checked: node.checked,
194	        content,
195	        indentation,
196	      });
197	    }
198	  });
199	
200	  return tasks;
201	}
